INSERT INTO "public"."societies" ("id", "name", "description", "start_date", "geo_code", "coordinator", "created_at") VALUES (1, 'IEEE Student Branch SREC', 'Started on 11 June 2001 under IEEE Madras Section. School Code: 41347756, Branch Code: 61491. Led by Principal Dr. A. Soundarrajan and Counselor Dr. K. Balamurugan.', '2001-06-11', '61491', 'Dr. K. Balamurugan', '2026-04-08 10:47:46.001617'), (2, 'IEEE Women in Engineering (WIE)', 'Started on 21 October 2009 to support and empower women engineers and scientists through technical and leadership development.', '2009-10-21', 'SBA61491', 'Mrs. Jansi Rani', '2026-04-08 10:47:46.001617'), (3, 'IEEE Engineering in Medicine and Biology Society (EMBS)', 'Started on 15 August 2018 focusing on biomedical engineering, healthcare technologies, and scientific innovation.', '2018-08-15', 'SBE61491', 'Dr. Deepa B Prabhu', '2026-04-08 10:47:46.001617'), (4, 'IEEE Computer Society (CS)', 'Started on 21 May 2019 focusing on computer science, AI, software development, and emerging technologies.', '2019-05-21', 'SBC61491A', 'Dr. J. Selvakumar', '2026-04-08 10:47:46.001617'), (5, 'IEEE Communication Society (ComSoc)', 'Started on 20 July 2024 focusing on communication systems, networking, and signal processing technologies.', '2024-07-20', 'SBC61491B', null, '2026-04-08 10:47:46.001617'), (6, 'IEEE Power Electronics Society (PELS)', 'Started on 28 October 2024 focusing on power electronics, renewable energy systems, and electrical innovations.', '2024-10-28', 'SBC61491C', 'Dr. C. Praveenkumar', '2026-04-08 10:47:46.001617'), (7, 'IEEE Instrumentation and Measurement Society (IM)', 'Started on 2 June 2025 focusing on measurement systems, instrumentation technologies, and precision engineering.', '2025-06-02', 'SBC61491D', 'Dr. Y. Dharsan', '2026-04-08 10:47:46.001617'), (8, 'IEEE Computational Intelligence Society (CIS)', 'Started on 2 June 2025 focusing on artificial intelligence, machine learning, and intelligent systems.', '2025-06-02', 'SBC61491D', null, '2026-04-08 10:47:46.001617');